import{_ as e,o as s,c as i,a2 as o}from"./chunks/framework.BW2T23B9.js";const u=JSON.parse('{"title":"如何丰富文档","description":"文档要变多，靠的是固定目录 + 改写已有材料 + 按读者分层，不是把应用仓库里的 Markdown 整盘搬过来。","frontmatter":{"description":"文档要变多，靠的是固定目录 + 改写已有材料 + 按读者分层，不是把应用仓库里的 Markdown 整盘搬过来。"},"headers":[],"relativePath":"guide/writing-docs.md","filePath":"guide/writing-docs.md","lastUpdated":1787830168000}'),n={name:"guide/writing-docs.md"};function t(d,a,l,c,r,p){return s(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="如何丰富文档" tabindex="-1">如何丰富文档 <a class="header-anchor" href="#如何丰富文档" aria-label="Permalink to &quot;如何丰富文档&quot;">​</a></h1><p>文档要变多，靠的是<strong>固定目录 + 改写已有材料 + 按读者分层</strong>，不是把应用仓库里的 Markdown 整盘搬过来。</p><p>Turna 已经有两处现成的内容源：</p><table tabindex="0"><thead><tr><th>来源</th><th>适合变成什么</th><th>不该原样公开的</th></tr></thead><tbody><tr><td>本仓库专题页（<code>anki.html</code>、<code>fsrs.html</code>、<code>ai.html</code>、<code>editor.html</code>、<code>curriculum.html</code>）</td><td>功能说明、概念入门</td><td>纯视觉演示代码</td></tr><tr><td>应用仓库 <code>Varnamalaplus/docs/</code></td><td>教师指南、课程约定、架构摘要</td><td>ADR、迁移计划、审计报告、施工 playbook</td></tr></tbody></table><p>应用仓库里目前大约有 70+ 篇 Markdown。其中大部分是一次性工程文档（<code>official-anki-migration/</code>、<code>*-plan.md</code>、<code>decisions/</code>）。这些对贡献者有用，对产品文档站点有害：会过期、难检索、读起来像工单。</p><h2 id="先定读者-再开目录" tabindex="-1">先定读者，再开目录 <a class="header-anchor" href="#先定读者-再开目录" aria-label="Permalink to &quot;先定读者，再开目录&quot;">​</a></h2><p>每一页只服务一类人：</p><ol><li><strong>学习者 / 访客</strong>：Turna 是什么、怎么跑起来、FSRS / Anki / AI 能做什么。</li><li><strong>老师 / 课程作者</strong>：怎么用编辑器改一课、JSON 目录怎么摆。</li><li><strong>开发者</strong>：架构从哪读、文档怎么加，而不是把 <code>project-guide.md</code> 整篇贴进来。</li></ol><p>对应到本站目录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>  index.md                 # 文档门户</span></span>
<span class="line"><span>  guide/                   # 学习者与访客</span></span>
<span class="line"><span>    what-is-turna.md</span></span>
<span class="line"><span>    getting-started.md</span></span>
<span class="line"><span>    features.md</span></span>
<span class="line"><span>    fsrs.md</span></span>
<span class="line"><span>    anki.md</span></span>
<span class="line"><span>    …</span></span>
<span class="line"><span>  authoring/               # 老师与课程作者</span></span>
<span class="line"><span>    teacher-guide.md</span></span>
<span class="line"><span>    course-layout.md</span></span></code></pre></div><p>新页面先问：它属于哪一类？然后只改对应 sidebar，不要另起一个平行站点。</p><h2 id="从已有材料改写-不要从零写" tabindex="-1">从已有材料改写，不要从零写 <a class="header-anchor" href="#从已有材料改写-不要从零写" aria-label="Permalink to &quot;从已有材料改写，不要从零写&quot;">​</a></h2><p>推荐顺序：</p><ol><li><strong>专题页 → <code>guide/</code></strong><br> 产品主页上的 Anki / FSRS / AI / 编辑器 / 课程页已经写过面向用户的句子。文档页用同样的事实，补上步骤、限制和链接，不要再写一套营销文案。</li><li><strong><code>project-guide.md</code> → 拆章节</strong><br> 应用仓库的项目指南是单一事实来源。按「复习 / Anki / AI / 编辑器 / 课程格式」各抽一章，改写成 1 屏能读完的文档页。不要整篇镜像。</li><li><strong><code>docs/authoring/</code> → <code>authoring/</code></strong><br> 教师指南、课型模板、课程目录约定已经是给人看的，几乎可以直接搬，只需改掉指向源码的相对路径。</li><li><strong>内容清单 → 课程页附录</strong><br><code>content_inventory_current.md</code> 适合摘要（Section 数、词汇数），不适合把 148 行词表贴进 VitePress。</li></ol><p>改写时保留：概念、步骤、限制、指向代码或专题页的链接。删掉：日期快照、测试计数、内部 ticket 号、已经做完的迁移阶段。</p><h2 id="一页一条任务" tabindex="-1">一页一条任务 <a class="header-anchor" href="#一页一条任务" aria-label="Permalink to &quot;一页一条任务&quot;">​</a></h2><ul><li>标题用读者会搜的词：「如何导入 Anki 牌组」，不要用「P5D remainder」。</li><li>开头三行说清楚「这页解决什么」。</li><li>步骤用编号列表；概念用短表。</li><li>文末只留 1–2 个「下一步」，把人送到下一层，而不是链到十个相关页。</li><li>过期的计划文档不要改写成指南，直接不收录。</li></ul><h2 id="加一篇新文档的步骤" tabindex="-1">加一篇新文档的步骤 <a class="header-anchor" href="#加一篇新文档的步骤" aria-label="Permalink to &quot;加一篇新文档的步骤&quot;">​</a></h2><ol><li>在 <code>docs/guide/</code> 或 <code>docs/authoring/</code> 新建 Markdown。</li><li>在 <code>docs/.vitepress/config.mts</code> 的 <code>sidebar</code> 里加一条。</li><li>从相关旧页链过来（<code>features.md</code>、文档首页、或专题 HTML）。</li><li>本地检查：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>从终端给出的主站地址点击「文档」，确认主站往返、侧栏、搜索和站内链接都通。只调试文档时可运行 <code>npm run docs:dev</code>，并打开 <a href="http://localhost:5174/docs/" target="_blank" rel="noreferrer">http://localhost:5174/docs/</a>。</p><ol start="5"><li><code>npm run build</code> 会把文档打进 <code>dist/docs/</code>，产品主页顶部的「文档」指向这里。</li></ol><h2 id="刻意不收录的内容" tabindex="-1">刻意不收录的内容 <a class="header-anchor" href="#刻意不收录的内容" aria-label="Permalink to &quot;刻意不收录的内容&quot;">​</a></h2><ul><li><code>docs/decisions/00xx-*.md</code>：ADR 留在应用仓库。</li><li><code>docs/official-anki-migration/</code>：施工过程，不是产品说明。</li><li>各类 <code>*-plan.md</code> / <code>*-audit.md</code> / <code>*-result-report.md</code>：做完即过期。</li><li>截图夹、fixture、CI 产物。</li></ul><p>如果贡献者需要这些，在开发者页用一句话链到应用仓库路径即可。</p><h2 id="让「量大」可检索" tabindex="-1">让「量大」可检索 <a class="header-anchor" href="#让「量大」可检索" aria-label="Permalink to &quot;让「量大」可检索&quot;">​</a></h2><p>页面变多之后，发现比写作更重要：</p><ul><li>打开 VitePress 本地搜索（本站已启用），标题和正文都能搜到。</li><li>同一件事只在一页讲透，其它页只链过去，避免三份互相打架的 FSRS 说明。</li><li>侧栏分组保持浅：开始 / 功能 / 课程 / 创作。超过两层读者就不会点。</li></ul><h2 id="和代码同步" tabindex="-1">和代码同步 <a class="header-anchor" href="#和代码同步" aria-label="Permalink to &quot;和代码同步&quot;">​</a></h2><p>文档不是第二个事实来源。行为变了，先改应用仓库的 <code>project-guide.md</code> 或 <code>authoring/</code>，再改本站对应页。本站负责「读得快」，应用仓库负责「写得全」。</p>`,30)])])}const g=e(n,[["render",t]]);export{u as __pageData,g as default};
